import{_ as a,o as e,c as i,a2 as l}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"TUI エクスプローラー","description":"","frontmatter":{},"headers":[],"relativePath":"ja/advanced/tui.md","filePath":"ja/advanced/tui.md","lastUpdated":1784903584000}'),o={name:"ja/advanced/tui.md"};function d(r,t,s,n,c,h){return e(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="tui-エクスプローラー" tabindex="-1">TUI エクスプローラー <a class="header-anchor" href="#tui-エクスプローラー" aria-label="Permalink to &quot;TUI エクスプローラー&quot;">​</a></h1><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><p>swag2mcp には組み込みの TUI（Terminal User Interface）が含まれており、対話的に API を探索できます。ターミナルから離れることなく API エンドポイントを検索、ブラウズ、調査、呼び出しできるフルスクリーンターミナルアプリケーションです。</p><h2 id="起動" tabindex="-1">起動 <a class="header-anchor" href="#起動" aria-label="Permalink to &quot;起動&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><p>設定ファイルが存在しない場合、TUI は自動的に初期化ウィザードを起動します。</p><h2 id="モード" tabindex="-1">モード <a class="header-anchor" href="#モード" aria-label="Permalink to &quot;モード&quot;">​</a></h2><p>TUI には 3 つのモードがあり、<code>Tab</code> キーで切り替えられます：</p><h3 id="検索モード" tabindex="-1">検索モード <a class="header-anchor" href="#検索モード" aria-label="Permalink to &quot;検索モード&quot;">​</a></h3><p>すべての spec の全エンドポイントに対する全文検索。<code>search</code> MCP ツールと同じクエリ構文をサポートします。</p><ul><li>クエリを入力してエンドポイント名、パス、説明を検索</li><li>メソッド、タグ、パスで結果をフィルタリング</li><li>1 回のキー操作でエンドポイントの詳細を表示</li><li>ページネーションで結果を移動（1 ページ 10 項目）</li></ul><h3 id="ブラウズモード" tabindex="-1">ブラウズモード <a class="header-anchor" href="#ブラウズモード" aria-label="Permalink to &quot;ブラウズモード&quot;">​</a></h3><p>spec 階層のツリー移動：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Spec → Collection → Tag → Endpoint</span></span></code></pre></div><ul><li>ツリーを下って特定のエンドポイントを見つける</li><li>エンドポイントの詳細を表示（パラメーター、リクエストボディ、レスポンス）</li><li>TUI から直接 API を呼び出す</li><li>エンドポイントの詳細を JSON ファイルとして保存</li></ul><h3 id="認証モード" tabindex="-1">認証モード <a class="header-anchor" href="#認証モード" aria-label="Permalink to &quot;認証モード&quot;">​</a></h3><p>任意の spec の認証トークンとヘッダーを表示。デバッグや curl コマンドの生成に便利です。</p><h2 id="コントロール" tabindex="-1">コントロール <a class="header-anchor" href="#コントロール" aria-label="Permalink to &quot;コントロール&quot;">​</a></h2><table tabindex="0"><thead><tr><th>キー</th><th>アクション</th></tr></thead><tbody><tr><td><code>↑</code> / <code>↓</code></td><td>上下に移動</td></tr><tr><td><code>Enter</code></td><td>選択または開く</td></tr><tr><td><code>Esc</code></td><td>1 つ前のレベルに戻る</td></tr><tr><td><code>Tab</code></td><td>検索、ブラウズ、認証モードを切り替え</td></tr><tr><td><code>/</code></td><td>検索入力をフォーカス</td></tr><tr><td><code>N</code> / <code>P</code></td><td>次 / 前のページ</td></tr><tr><td><code>B</code></td><td>前の画面に戻る</td></tr><tr><td><code>M</code></td><td>メインメニューに戻る</td></tr><tr><td><code>S</code></td><td>エンドポイントの詳細を JSON ファイルとして保存</td></tr><tr><td><code>q</code> / <code>Ctrl+C</code></td><td>終了</td></tr></tbody></table><h2 id="状態" tabindex="-1">状態 <a class="header-anchor" href="#状態" aria-label="Permalink to &quot;状態&quot;">​</a></h2><p>移動中に TUI は以下の状態を経由します：</p><ol><li><strong>Loading</strong> — ワークスペースからデータを読み込み中</li><li><strong>Search</strong> — クエリ入力のある検索モード</li><li><strong>Browse</strong> — spec リストのあるブラウズモード</li><li><strong>Spec List</strong> — すべての spec のリスト</li><li><strong>Collection List</strong> — spec 内の collection</li><li><strong>Tag List</strong> — collection 内のタグ</li><li><strong>Endpoint List</strong> — タグ内のエンドポイント</li><li><strong>Endpoint Detail</strong> — 完全なエンドポイント情報</li><li><strong>Invoke Result</strong> — API 呼び出し結果</li><li><strong>Error</strong> — メッセージ付きエラー状態</li></ol><h2 id="エンドポイント詳細表示" tabindex="-1">エンドポイント詳細表示 <a class="header-anchor" href="#エンドポイント詳細表示" aria-label="Permalink to &quot;エンドポイント詳細表示&quot;">​</a></h2><p>エンドポイントを選択すると、TUI は以下を表示します：</p><ul><li>HTTP メソッドとパス</li><li>ベース URL と完全な URL</li><li>サマリーと説明</li><li>すべてのパラメーター（名前、場所、型、必須）</li><li>リクエストボディスキーマ（該当する場合）</li><li>レスポンスコードとスキーマ</li><li>非推奨ステータス</li></ul><h2 id="要件" tabindex="-1">要件 <a class="header-anchor" href="#要件" aria-label="Permalink to &quot;要件&quot;">​</a></h2><ul><li><strong>ターミナルサイズ:</strong> 最低 80×24 文字</li><li><strong>ターミナルエミュレーター:</strong> 最新のほとんどのターミナルで動作（iTerm2、Terminal.app、GNOME Terminal、Windows Terminal など）</li><li><strong>SSH:</strong> SSH 接続でも動作</li></ul><h2 id="重要な注意点" tabindex="-1">重要な注意点 <a class="header-anchor" href="#重要な注意点" aria-label="Permalink to &quot;重要な注意点&quot;">​</a></h2><ul><li><strong>自動初期化</strong> — 設定ファイルが存在しない場合、TUI は自動的に初期化ウィザードを起動します</li><li><strong>ページネーション</strong> — リストは 1 ページ 10 項目でページネーションされます。<code>N</code> と <code>P</code> で移動</li><li><strong>エンドポイント詳細の保存</strong> — エンドポイント詳細表示で <code>S</code> を押すと、完全な詳細をカレントディレクトリに JSON ファイルとして保存</li><li><strong>認証モード</strong> — デバッグ用のトークンとヘッダーを表示。本番環境では <code>--disable-llm-auth</code> で認証ツールを無効化できます</li></ul>',29)])])}const g=a(o,[["render",d]]);export{u as __pageData,g as default};
